#!/usr/bin/env bash
# rtl/vendor/update_pulp.sh — (re)vendor the PULP AXI crossbar and CDC.
#
# Copies only the files axi_xbar + axi_cdc actually need (31 sources, 4
# headers) from pinned releases, then applies ONE local change:
#
#   Every macro defined in common_cells/assertions.svh is renamed with a
#   PULP_ prefix (`ASSERT -> `PULP_ASSERT, `INC_ASSERT -> `PULP_INC_ASSERT, ...).
#   OpenTitan's prim_assert.sv defines the same 18 names with different
#   argument lists; without the rename, whichever library compiles last
#   silently redefines the other's macros.
#
# Output: rtl/vendor/pulp/{src,include}, rtl/vendor/pulp/pulp.f, VERSIONS.
# Idempotent. Needs network access to github.com.
set -euo pipefail

AXI_TAG=v0.39.11            # axi Bender.yml asks for common_cells 1.39.0
CC_TAG=v1.39.0

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
out="${here}/pulp"
tmp="$(mktemp -d)"
trap 'rm -rf "${tmp}"' EXIT

git -c advice.detachedHead=false clone -q --depth 1 --branch "${AXI_TAG}" https://github.com/pulp-platform/axi.git          "${tmp}/axi"
git -c advice.detachedHead=false clone -q --depth 1 --branch "${CC_TAG}"  https://github.com/pulp-platform/common_cells.git "${tmp}/cc"

# Compile order matters: packages first, then leaves, then users.
CC_SRC=(cf_math_pkg lzc delta_counter counter binary_to_gray gray_to_binary sync
        fifo_v3 spill_register_flushable spill_register stream_register rr_arb_tree
        addr_decode_dync addr_decode cdc_fifo_gray)
AXI_SRC=(axi_pkg axi_intf axi_atop_filter axi_cut axi_multicut axi_demux_id_counters
         axi_demux_simple axi_demux axi_id_prepend axi_mux axi_err_slv
         axi_xbar_unmuxed axi_xbar axi_cdc_src axi_cdc_dst axi_cdc)

rm -rf "${out}"
mkdir -p "${out}/src" "${out}/include/axi" "${out}/include/common_cells" "${out}/licenses"
for f in "${CC_SRC[@]}";  do cp "${tmp}/cc/src/${f}.sv"  "${out}/src/"; done
for f in "${AXI_SRC[@]}"; do cp "${tmp}/axi/src/${f}.sv" "${out}/src/"; done
cp "${tmp}"/axi/include/axi/{assign,typedef}.svh            "${out}/include/axi/"
cp "${tmp}"/cc/include/common_cells/{assertions,registers}.svh "${out}/include/common_cells/"
cp "${tmp}/axi/LICENSE" "${out}/licenses/LICENSE.axi"
cp "${tmp}/cc/LICENSE"  "${out}/licenses/LICENSE.common_cells"

# --- the one local change: namespace the assertion macros ---------------------
macros=$(grep -oE '`define[[:space:]]+[A-Za-z_][A-Za-z0-9_]*' \
           "${out}/include/common_cells/assertions.svh" | awk '{print $2}' | sort -u)
sed_args=()
for m in ${macros}; do
  [[ "${m}" == COMMON_CELLS_ASSERTIONS_SVH ]] && continue
  sed_args+=(-e "s/\`${m}\b/\`PULP_${m}/g"            # uses:     `ASSERT(...)
             -e "s/\(\`\(define\|ifdef\|ifndef\|undef\)[[:space:]]\+\)${m}\b/\1PULP_${m}/g")
done
sed -i "${sed_args[@]}" "${out}"/src/*.sv "${out}"/include/*/*.svh

# --- file list ----------------------------------------------------------------
{
  echo "// Generated by rtl/vendor/update_pulp.sh — do not edit."
  echo "+incdir+\${TITAN_ROOT}/rtl/vendor/pulp/include"
  for f in "${CC_SRC[@]}" "${AXI_SRC[@]}"; do
    echo "\${TITAN_ROOT}/rtl/vendor/pulp/src/${f}.sv"
  done
} > "${out}/pulp.f"

{
  echo "axi          ${AXI_TAG}  $(git -C "${tmp}/axi" rev-parse HEAD)"
  echo "common_cells ${CC_TAG}  $(git -C "${tmp}/cc"  rev-parse HEAD)"
  echo "local change: assertion macros renamed with PULP_ prefix (see update_pulp.sh)"
} > "${out}/VERSIONS"

echo "vendored $(ls "${out}/src" | wc -l) sources into ${out}"
